#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<long long> input_data;
    long long val;
    while (cin >> val) {
        input_data.push_back(val);
    }
    int n = (int)input_data[0];
    int mod = (int)input_data[1];

    auto add_mod = [&](long long a, long long b) {
        return (a + b) % mod;
    };

    auto mul_mod = [&](long long a, long long b) {
        return (a * b) % mod;
    };

    vector<long long> mem = {0, 1};
    long long total = 1;

    for (int i = 2; i <= n; ++i) {
        int sqrt_limit = (int)std::sqrt(i) + 1;
        long long current = total;

        for (int f = 2; f < sqrt_limit; ++f) {
            current = add_mod(current, mem[i / f]);
        }

        int boundary = i;
        for (int j = 1; j <= i / sqrt_limit; ++j) {
            int nxt = i / (j + 1);
            current = add_mod(current, mul_mod(boundary - nxt, mem[j]));
            boundary = nxt;
        }

        total = add_mod(total, current);
        mem.push_back(current);
    }

    cout << mem.back() << "\n";

    return 0;
}
